import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { useScroll } from '@react-three/drei';
import * as THREE from 'three';

const fireVertexShader = `
  uniform float uTime;
  uniform float uScale;
  attribute float aSize;
  varying vec3 vColor;
  
  // Simplex 3D Noise 
  vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
  vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
  float snoise(vec3 v){ 
    const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
    const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i  = floor(v + dot(v, C.yyy) );
    vec3 x0 = v - i + dot(i, C.xxx) ;
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min( g.xyz, l.zxy );
    vec3 i2 = max( g.xyz, l.zxy );
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod(i, 289.0);
    vec4 p = permute( permute( permute( 
               i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
             + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
             + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));
    float n_ = 0.142857142857; 
    vec3  ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z *ns.z);  
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_ );    
    vec4 x = x_ *ns.x + ns.yyyy;
    vec4 y = y_ *ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4( x.xy, y.xy );
    vec4 b1 = vec4( x.zw, y.zw );
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;
    vec3 p0 = vec3(a0.xy,h.x);
    vec3 p1 = vec3(a0.zw,h.y);
    vec3 p2 = vec3(a1.xy,h.z);
    vec3 p3 = vec3(a1.zw,h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
    p0 *= norm.x;
    p1 *= norm.y;
    p2 *= norm.z;
    p3 *= norm.w;
    vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3) ) );
  }

  void main() {
    vec3 pos = position;
    
    // Upward flow based on time and height
    // We loop the y position to create endless fire
    float flowTime = uTime * 2.0;
    pos.y = mod(pos.y + flowTime, 10.0); // Flame height max 10
    
    // Add time based noise to curl the flames
    float noise1 = snoise(vec3(pos.x * 0.5, pos.y * 0.5 - uTime * 3.0, pos.z * 0.5));
    float noise2 = snoise(vec3(pos.x * 0.8 + 10.0, pos.y * 0.8 - uTime * 4.0, pos.z * 0.8 + 10.0));
    
    // Pinch at the top, spread at bottom
    float width = smoothstep(10.0, 0.0, pos.y) * 3.0; 
    
    pos.x = (pos.x * width) + (noise1 * pos.y * 0.3);
    pos.z = (pos.z * width) + (noise2 * pos.y * 0.3);
    
    // Scale everything based on scroll progress
    pos *= uScale;
    
    vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
    
    // Color mapping based on height (Y)
    float h = clamp(pos.y / 10.0, 0.0, 1.0);
    
    // Ember (Bottom), Flame (Middle), Smoke (Top)
    vec3 cEmber = vec3(1.0, 0.8, 0.2);
    vec3 cFlame = vec3(1.0, 0.2, 0.0);
    vec3 cSmoke = vec3(0.1, 0.0, 0.0);
    
    if(h < 0.2) {
        vColor = mix(cEmber, cFlame, h / 0.2);
    } else {
        vColor = mix(cFlame, cSmoke, pow((h - 0.2) / 0.8, 2.0));
    }
    
    // Make particles smaller at the top
    float sizeMod = smoothstep(10.0, 0.0, pos.y);
    gl_PointSize = aSize * sizeMod * (150.0 / -mvPosition.z) * uScale;
    gl_Position = projectionMatrix * mvPosition;
  }
`;

const fireFragmentShader = `
  varying vec3 vColor;
  void main() {
    // Soft circle
    vec2 center = gl_PointCoord - 0.5;
    float dist = length(center);
    if(dist > 0.5) discard;
    
    float alpha = smoothstep(0.5, 0.1, dist);
    
    gl_FragColor = vec4(vColor, alpha * 0.9);
  }
`;

const DigitalFire = ({ position }) => {
  const pointsRef = useRef();
  const materialRef = useRef();
  const scroll = useScroll();
  
  const particleCount = 50000;
  
  // Initialize particles in a cylinder volume
  const particles = useMemo(() => {
    const positions = new Float32Array(particleCount * 3);
    const sizes = new Float32Array(particleCount);
    
    for (let i = 0; i < particleCount; i++) {
      // Cylinder distribution
      const r = Math.sqrt(Math.random());
      const theta = Math.random() * 2 * Math.PI;
      
      positions[i * 3] = r * Math.cos(theta); // x
      positions[i * 3 + 1] = Math.random() * 10; // y (0 to 10 height)
      positions[i * 3 + 2] = r * Math.sin(theta); // z
      
      sizes[i] = 1.0 + Math.random() * 2.0;
    }
    
    return { positions, sizes };
  }, []);

  const uniforms = useMemo(() => ({
    uTime: { value: 0 },
    uScale: { value: 0 },
  }), []);

  useFrame((state) => {
    if (!pointsRef.current) return;
    
    uniforms.uTime.value = state.clock.elapsedTime;
    
    const globalProgress = scroll.offset;
    const progress = THREE.MathUtils.clamp((globalProgress - 0.08) / 0.08, 0, 1);
    
    // Scale fire based on progress. Ignites around progress 0.3, max at 0.6
    const fireScale = THREE.MathUtils.clamp((progress - 0.3) * 3.0, 0, 1);
    
    // Animate the scale with a slight flicker
    const flicker = 1.0 + Math.sin(state.clock.elapsedTime * 15) * 0.02;
    uniforms.uScale.value = fireScale * 2.5 * flicker;
  });

  return (
    <group position={position}>
      <points ref={pointsRef}>
        <bufferGeometry>
          <bufferAttribute
            attach="attributes-position"
            count={particleCount}
            array={particles.positions}
            itemSize={3}
          />
          <bufferAttribute
            attach="attributes-aSize"
            count={particleCount}
            array={particles.sizes}
            itemSize={1}
          />
        </bufferGeometry>
        <shaderMaterial
          ref={materialRef}
          vertexShader={fireVertexShader}
          fragmentShader={fireFragmentShader}
          uniforms={uniforms}
          transparent={true}
          blending={THREE.AdditiveBlending}
          depthWrite={false}
        />
      </points>
      <pointLight color="#ff4400" intensity={4} distance={150} position={[0, 10, 0]} />
    </group>
  );
};

export default DigitalFire;
