import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { useScroll } from '@react-three/drei';
import * as THREE from 'three';

const StylizedHumanoid = ({ position, rotation, delay }) => {
  const groupRef = useRef();
  const headRef = useRef();
  const bodyRef = useRef();
  const armsRef = useRef();
  const phoneRef = useRef();
  const scroll = useScroll();

  useFrame((state) => {
    if (!groupRef.current) return;
    
    const globalProgress = scroll.offset;
    const localProgress = THREE.MathUtils.clamp((globalProgress - 0.08) / 0.08, 0, 1);
    const thawFactor = THREE.MathUtils.smoothstep(localProgress, 0.2, 0.8);
    
    // Animate based on thawFactor
    // Phase 1 (thaw=0): Looking down, arms up holding phone
    // Phase 3 (thaw=1): Looking up, arms down, jumping towards fire
    
    const t = THREE.MathUtils.clamp((thawFactor - delay) * 2.0, 0, 1);
    
    // Head looks up
    headRef.current.rotation.x = THREE.MathUtils.lerp(0.5, -0.2, t);
    
    // Arms drop
    armsRef.current.rotation.x = THREE.MathUtils.lerp(-0.8, 0, t);
    
    // Phone fades/drops
    phoneRef.current.position.y = THREE.MathUtils.lerp(0, -5, t);
    phoneRef.current.material.opacity = 1 - t;
    
    // Jump towards fire
    const jump = Math.sin(state.clock.elapsedTime * 8 + delay * 10) * t;
    groupRef.current.position.y = position[1] + (jump > 0 ? jump * 2 : 0);
    
    // Move towards center (0, 0, centerZ)
    if (t > 0) {
       const dir = new THREE.Vector3(0, position[1], position[2]).sub(new THREE.Vector3(position[0], position[1], position[2])).normalize();
       groupRef.current.position.x = position[0] + dir.x * (t * 15);
       groupRef.current.position.z = position[2] + dir.z * (t * 15);
    } else {
       groupRef.current.position.x = position[0];
       groupRef.current.position.z = position[2];
    }
  });

  return (
    <group ref={groupRef} position={position} rotation={rotation}>
      {/* Body */}
      <mesh ref={bodyRef} position={[0, 3, 0]}>
        <capsuleGeometry args={[1, 3, 4, 8]} />
        <meshStandardMaterial color="#222" roughness={0.8} />
      </mesh>
      
      {/* Head */}
      <mesh ref={headRef} position={[0, 6.5, 0]}>
        <sphereGeometry args={[1.2, 8, 8]} />
        <meshStandardMaterial color="#333" roughness={0.7} />
      </mesh>
      
      {/* Arms */}
      <group ref={armsRef} position={[0, 4.5, 0]}>
        <mesh position={[-1.5, -1.5, 1]}>
          <capsuleGeometry args={[0.4, 2, 4, 8]} />
          <meshStandardMaterial color="#222" roughness={0.8} />
        </mesh>
        <mesh position={[1.5, -1.5, 1]}>
          <capsuleGeometry args={[0.4, 2, 4, 8]} />
          <meshStandardMaterial color="#222" roughness={0.8} />
        </mesh>
      </group>
      
      {/* Glowing Phone */}
      <mesh ref={phoneRef} position={[0, 4.5, 2]}>
        <boxGeometry args={[0.8, 1.5, 0.1]} />
        <meshBasicMaterial color="#00ffcc" transparent={true} />
      </mesh>
    </group>
  );
};

const IcebreakerSilhouettes = ({ position }) => {
  const numPeople = 25;
  const radius = 60;
  
  const peopleData = useMemo(() => {
    const data = [];
    for (let i = 0; i < numPeople; i++) {
      const angle = (i / numPeople) * Math.PI * 2 + (Math.random() * 0.2);
      const r = radius + Math.random() * 40;
      data.push({
        position: [
          position[0] + Math.cos(angle) * r,
          position[1] - 30, 
          position[2] + Math.sin(angle) * r
        ],
        // Look towards center
        rotation: [0, -angle - Math.PI / 2, 0],
        delay: Math.random() * 0.5
      });
    }
    return data;
  }, [numPeople, position, radius]);

  return (
    <group>
      {peopleData.map((data, i) => (
        <StylizedHumanoid key={i} {...data} />
      ))}
    </group>
  );
};

export default IcebreakerSilhouettes;
