import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const Candlestick = ({ position, rotation, color, bodyHeight }) => {
  return (
    <group position={position} rotation={rotation}>
      {/* Wick */}
      <mesh position={[0, 0, 0]}>
        <cylinderGeometry args={[2, 2, bodyHeight + 40, 8]} />
        <meshStandardMaterial color={color} roughness={0.4} emissive={color} emissiveIntensity={0.2} />
      </mesh>
      {/* Body */}
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[10, bodyHeight, 10]} />
        <meshStandardMaterial color={color} roughness={0.4} emissive={color} emissiveIntensity={0.8} />
      </mesh>
    </group>
  );
};

// Layout for "CQ" made of candlesticks
const getCQLayout = () => {
  const points = [];
  const addCandle = (x, y, color) => {
    points.push({ x, y, color, bodyHeight: 40 + Math.random() * 40 });
  };
  
  // "C" shape
  for (let a = Math.PI * 0.25; a < Math.PI * 1.75; a += 0.2) {
    addCandle( -100 + Math.cos(a) * 80, Math.sin(a) * 80, "#00ff00" );
  }
  
  // "Q" shape (O part)
  for (let a = 0; a < Math.PI * 2; a += 0.2) {
    addCandle( 100 + Math.cos(a) * 80, Math.sin(a) * 80, "#ff0044" );
  }
  // "Q" tail
  addCandle( 140, -40, "#ff0044" );
  addCandle( 160, -60, "#ff0044" );
  addCandle( 180, -80, "#ff0044" );
  
  return points;
};

const WormholeContango = ({ position, rotation = [0, 0, 0], length = 3000, radius = 250, visible }) => {
  const groupRef = useRef();

  const candlesticks = useMemo(() => {
    const items = [];
    const count = Math.floor(length / 5); 
    for (let i = 0; i < count; i++) {
      const z = -(i / count) * length;
      const t = i * 0.1;
      
      const x1 = Math.cos(t) * radius;
      const y1 = Math.sin(t) * radius;
      
      const x2 = Math.cos(t + Math.PI) * radius;
      const y2 = Math.sin(t + Math.PI) * radius;

      const isBull = Math.random() > 0.5;
      const color = isBull ? "#00ff00" : "#ff0044";
      const bodyHeight = 20 + Math.random() * 60;
      
      const rot1 = [0, 0, t + Math.PI / 2];
      const rot2 = [0, 0, t + Math.PI + Math.PI / 2];

      items.push({ x: x1, y: y1, z, rot: rot1, color, bodyHeight });
      items.push({ x: x2, y: y2, z, rot: rot2, color, bodyHeight });
    }
    return items;
  }, [length, radius]);

  const cqCandles = useMemo(() => getCQLayout(), []);

  useFrame((state) => {
    if (groupRef.current && visible) {
      groupRef.current.rotation.z = state.clock.elapsedTime * 0.5;
    }
  });

  return (
    <group position={position} rotation={rotation} visible={visible}>
      <group ref={groupRef}>
        {candlesticks.map((c, i) => (
          <Candlestick 
            key={`tunnel-${i}`} 
            position={[c.x, c.y, c.z]} 
            rotation={c.rot} 
            color={c.color} 
            bodyHeight={c.bodyHeight} 
          />
        ))}
      </group>
      
      {/* CQ Logo at the end of the wormhole */}
      <group position={[0, 0, -length - 100]}>
        {cqCandles.map((c, i) => (
          <Candlestick 
            key={`cq-${i}`} 
            position={[c.x, c.y, 0]} 
            rotation={[Math.PI / 2, 0, 0]} 
            color={c.color} 
            bodyHeight={c.bodyHeight} 
          />
        ))}
      </group>
      
      {/* Central glow */}
      <mesh position={[0, 0, -length / 2]} rotation={[Math.PI / 2, 0, 0]}>
        <cylinderGeometry args={[radius * 0.8, radius * 0.8, length, 32, 1, true]} />
        <meshBasicMaterial color="#00ff00" transparent opacity={0.05} side={THREE.BackSide} />
      </mesh>
    </group>
  );
};

export default WormholeContango;
