import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { useScroll, Text } from '@react-three/drei';
import * as THREE from 'three';
import DigitalFire from './icebreaker/DigitalFire';
import IcebreakerSilhouettes from './icebreaker/IcebreakerSilhouettes';

const iceVertexShader = `
  uniform float uTime;
  uniform float uTransition;
  varying vec2 vUv;
  varying vec3 vPosition;
  varying float vElevation;

  // Classic Perlin 3D Noise 
  vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
  vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
  vec3 fade(vec3 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}
  float cnoise(vec3 P){
    vec3 Pi0 = floor(P); vec3 Pi1 = Pi0 + vec3(1.0);
    Pi0 = mod(Pi0, 289.0); Pi1 = mod(Pi1, 289.0);
    vec3 Pf0 = fract(P); vec3 Pf1 = Pf0 - vec3(1.0);
    vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
    vec4 iy = vec4(Pi0.yy, Pi1.yy);
    vec4 iz0 = Pi0.zzzz; vec4 iz1 = Pi1.zzzz;
    vec4 ixy = permute(permute(ix) + iy);
    vec4 ixy0 = permute(ixy + iz0); vec4 ixy1 = permute(ixy + iz1);
    vec4 gx0 = ixy0 / 7.0; vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
    gx0 = fract(gx0);
    vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
    vec4 sz0 = step(gz0, vec4(0.0));
    gx0 -= sz0 * (step(0.0, gx0) - 0.5); gy0 -= sz0 * (step(0.0, gy0) - 0.5);
    vec4 gx1 = ixy1 / 7.0; vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
    gx1 = fract(gx1);
    vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
    vec4 sz1 = step(gz1, vec4(0.0));
    gx1 -= sz1 * (step(0.0, gx1) - 0.5); gy1 -= sz1 * (step(0.0, gy1) - 0.5);
    vec3 g000 = vec3(gx0.x,gy0.x,gz0.x); vec3 g100 = vec3(gx0.y,gy0.y,gz0.y);
    vec3 g010 = vec3(gx0.z,gy0.z,gz0.z); vec3 g110 = vec3(gx0.w,gy0.w,gz0.w);
    vec3 g001 = vec3(gx1.x,gy1.x,gz1.x); vec3 g101 = vec3(gx1.y,gy1.y,gz1.y);
    vec3 g011 = vec3(gx1.z,gy1.z,gz1.z); vec3 g111 = vec3(gx1.w,gy1.w,gz1.w);
    vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
    g000 *= norm0.x; g010 *= norm0.y; g100 *= norm0.z; g110 *= norm0.w;
    vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
    g001 *= norm1.x; g011 *= norm1.y; g101 *= norm1.z; g111 *= norm1.w;
    float n000 = dot(g000, Pf0); float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
    float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z)); float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
    float n001 = dot(g001, vec3(Pf0.xy, Pf1.z)); float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
    float n011 = dot(g011, vec3(Pf0.x, Pf1.yz)); float n111 = dot(g111, Pf1);
    vec3 fade_xyz = fade(Pf0);
    vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
    vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
    float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x); 
    return 2.2 * n_xyz;
  }

  void main() {
    vUv = uv;
    
    // We are inside a cylinder of radius 50.
    // Displace vertices inwards/outwards to create jagged cavern walls.
    
    // Base large shapes (mountains/spikes)
    float noise1 = cnoise(position * 0.05);
    // Detail shapes
    float noise2 = cnoise(position * 0.15) * 0.5;
    
    float totalNoise = noise1 + noise2;
    
    // Jagged ice ridges (sharp absolute value)
    float icyDisplacement = abs(totalNoise) * 30.0;
    
    // Smooth sand dunes
    float sandDisplacement = totalNoise * 10.0 + 5.0; 
    
    // Blend based on transition (Ice melts into smooth sand dunes)
    float finalDisplacement = mix(icyDisplacement, sandDisplacement, uTransition);
    
    // Direction is normal (which points outwards in cylinder, but we want it inwards)
    vec3 newPosition = position - normal * finalDisplacement;
    
    vPosition = newPosition;
    vElevation = finalDisplacement;
    
    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
  }
`;

const iceFragmentShader = `
  uniform float uTime;
  uniform float uTransition;
  uniform float uOpacity;
  varying vec2 vUv;
  varying vec3 vPosition;
  varying float vElevation;

  void main() {
    // Coloring based on elevation (displacement depth)
    // Cold: Icy blue crevices, bright cyan peaks
    vec3 coldLow = vec3(0.01, 0.05, 0.15);
    vec3 coldHigh = vec3(0.3, 0.8, 1.0);
    vec3 colorCold = mix(coldLow, coldHigh, smoothstep(0.0, 30.0, vElevation));
    
    // Warm: Deep sand crevices, bright sand peaks
    vec3 warmLow = vec3(0.4, 0.2, 0.05);
    vec3 warmHigh = vec3(0.9, 0.7, 0.3);
    vec3 colorWarm = mix(warmLow, warmHigh, smoothstep(0.0, 15.0, vElevation));
    
    // Add fire glow tint when melting
    vec3 fireGlow = vec3(1.0, 0.4, 0.0) * uTransition * 0.5 * smoothstep(30.0, 0.0, vElevation);
    
    vec3 finalColor = mix(colorCold, colorWarm, uTransition) + fireGlow;
    
    float zDist = abs(vPosition.y); // Y is length in local cylinder space
    float alpha = uOpacity * smoothstep(1100.0, 800.0, zDist);
    
    gl_FragColor = vec4(finalColor, alpha);
  }
`;

const WorldIcebreaker = ({ position, rotation, visible }) => {
  const materialRef = useRef();
  const scroll = useScroll();
  
  const uniforms = useMemo(() => ({
    uTime: { value: 0 },
    uTransition: { value: 0 },
    uOpacity: { value: 1.0 }
  }), []);

  useFrame((state) => {
    if (materialRef.current && visible) {
      materialRef.current.uniforms.uTime.value = state.clock.elapsedTime;
      
      const globalProgress = scroll.offset;
      const localProgress = THREE.MathUtils.clamp((globalProgress - 0.08) / 0.08, 0, 1);
      
      const transitionProgress = THREE.MathUtils.smoothstep(localProgress, 0.2, 0.8);
      materialRef.current.uniforms.uTransition.value = transitionProgress;
    }
  });

  if (!visible) return null;

  return (
    <group position={position} rotation={rotation}>
      {/* 
        High density cylinder: radius 60, length 2200, 128 radial segments, 300 height segments.
        This provides ~38,000 vertices for stunning detailed displacement mapping.
      */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
        <cylinderGeometry args={[60, 60, 2000, 128, 300, true]} />
        <shaderMaterial
          ref={materialRef}
          vertexShader={iceVertexShader}
          fragmentShader={iceFragmentShader}
          uniforms={uniforms}
          transparent={true}
          side={THREE.BackSide}
          wireframe={false}
        />
      </mesh>
      
      <DigitalFire position={[0, -10, 0]} />
      <IcebreakerSilhouettes position={[0, -10, 0]} />

      <Text 
        position={[0, 10, 500]} 
        fontSize={15} 
        color="#ffffff" 
        outlineWidth={0.03} 
        outlineColor="#00ffff" 
        font="/fonts/Inter-Bold.woff"
      >
        ICEBREAKER
      </Text>
      
      <Text 
        position={[0, 0, 500]} 
        fontSize={4} 
        color="#00ffff" 
      >
        THE REAL-WORLD SOCIAL PROTOCOL
      </Text>
    </group>
  );
};

export default WorldIcebreaker;